public class Main {
    enum Day {
        MON, TUE, WED, THU, FRI, SAT, SUN
    }

    static boolean isRest(Day d) {
        switch (d) {
            case SAT:
            case SUN:
                return true;
            default:
                return false;
        }
    }

    public static void main(String[] args) {
        System.out.println(isRest(Day.SAT));
        System.out.println(isRest(Day.WED));
    }
}
